+            ...(output === undefined ? {} : { capturedOutput: output }),
+            diagnostics: {
+              stage: "cleanup",
+              java_module_observation: {
+                compiler: observed.value.compiler,
+                major: observed.value.major,
+              },
+            },
+          });
+        } else if (preparation !== undefined) {
+          primary = new ProviderAdapterError("jadx", operation, {
