+    expect(relations).toHaveLength(1);
+    expect(relations[0]?.resolution).toBe("resolved");
+    const slot = graph.nodes.find(
+      (node) => node.node_id === relations[0]?.source_node_id,
+    );
+    expect(slot?.properties.property_path).toEqual(path);
+  },
+);
+
